import { sqliteTable, text, integer, index, uniqueIndex } from "drizzle-orm/sqlite-core";

// ─────────────────────────────────────────────────────────────────────────────
// Cloudflare D1 (SQLite) schema.
//
// Differences from the Postgres original, all forced by SQLite:
//   • No `uuid` type and no `defaultRandom()` — ids are TEXT, generated by the
//     client (crypto.randomUUID) or by `$defaultFn` on the server.
//   • No `timestamptz` — every timestamp is ISO-8601 TEXT (UTC, `…Z`). Text
//     sorts lexicographically in the same order as the instants it encodes, so
//     `ORDER BY updated_at` and `WHERE updated_at < ?` stay correct.
//   • No `boolean` — `enabled`-style flags would be INTEGER 0/1. This app has
//     none left (reminders were out of scope), so nothing to convert.
//   • No `date` type — `activity_date` is TEXT `YYYY-MM-DD`, which is also what
//     the client already used.
//   • No `bigint` — `files.size` is INTEGER (SQLite integers are 64-bit).
// ─────────────────────────────────────────────────────────────────────────────

const isoNow = () => new Date().toISOString();

// ── users ────────────────────────────────────────────────────────────────────
export const users = sqliteTable("users", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  email: text("email").notNull().unique(),
  // PBKDF2-SHA256, stored as `pbkdf2$<iterations>$<salt-b64>$<hash-b64>`.
  // Null for a user that has never set a password (reserved for future SSO).
  passwordHash: text("password_hash"),
  name: text("name"),
  role: text("role").notNull().default("user"), // 'user' | 'admin'
  createdAt: text("created_at").notNull().$defaultFn(isoNow),
});

// ── sessions ─────────────────────────────────────────────────────────────────
// The JWT carries the session id in `jti`; this row is what makes a session
// revocable. Without it a stolen cookie stays valid until it expires, because
// nothing on the server can say "that token was logged out".
export const sessions = sqliteTable(
  "sessions",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: text("created_at").notNull().$defaultFn(isoNow),
    expiresAt: text("expires_at").notNull(),
    revokedAt: text("revoked_at"),
  },
  (t) => [index("sessions_user_idx").on(t.userId)],
);

// ── categories ───────────────────────────────────────────────────────────────
// Reference data, seeded by the migration (not a seed script) so a freshly
// created D1 database has the fourteen categories before the first request.
export const categories = sqliteTable("categories", {
  slug: text("slug").primaryKey(),
  label: text("label").notNull(),
  color: text("color").notNull(),
  icon: text("icon").notNull(),
  sortOrder: integer("sort_order").notNull().default(0),
});

// ── activities ───────────────────────────────────────────────────────────────
export const activities = sqliteTable(
  "activities",
  {
    id: text("id").primaryKey(),
    ownerId: text("owner_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    category: text("category").notNull(),
    title: text("title").notNull(),
    durationMinutes: integer("duration_minutes").notNull(),
    activityDate: text("activity_date").notNull(), // YYYY-MM-DD
    startTime: text("start_time"), // "HH:MM" local wall clock
    notes: text("notes"),
    intensity: text("intensity"), // light | moderate | hard
    location: text("location"), // home | office | gym | outdoors | other
    tags: text("tags"), // comma-separated, normalised
    createdAt: text("created_at").notNull().$defaultFn(isoNow),
    updatedAt: text("updated_at").notNull().$defaultFn(isoNow),
    // Soft-delete tombstone: a deletion travels as this timestamp instead of a
    // hard DELETE, so a device that was offline cannot resurrect a row another
    // device removed (last-write-wins on updated_at).
    deletedAt: text("deleted_at"),
  },
  (t) => [
    index("activities_owner_idx").on(t.ownerId),
    index("activities_owner_date_idx").on(t.ownerId, t.activityDate),
    index("activities_owner_updated_idx").on(t.ownerId, t.updatedAt),
  ],
);

// ── goals ────────────────────────────────────────────────────────────────────
// One row per (owner, category): either a daily or a weekly target in minutes.
export const goals = sqliteTable(
  "goals",
  {
    id: text("id").primaryKey(),
    ownerId: text("owner_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    category: text("category").notNull(),
    period: text("period").notNull().default("daily"), // 'daily' | 'weekly'
    targetMinutes: integer("target_minutes").notNull(),
    createdAt: text("created_at").notNull().$defaultFn(isoNow),
    updatedAt: text("updated_at").notNull().$defaultFn(isoNow),
    deletedAt: text("deleted_at"),
  },
  (t) => [
    uniqueIndex("goals_owner_category_idx").on(t.ownerId, t.category),
    index("goals_owner_idx").on(t.ownerId),
  ],
);

export type Activity = typeof activities.$inferSelect;
export type NewActivity = typeof activities.$inferInsert;
export type Category = typeof categories.$inferSelect;
export type Goal = typeof goals.$inferSelect;
export type NewGoal = typeof goals.$inferInsert;
export type User = typeof users.$inferSelect;
export type Session = typeof sessions.$inferSelect;
